import { Img, Section, Text } from '@react-email/components'
import * as React from 'react'

interface EmailHeaderProps {
  /**
   * Absolute URL to apps/landing/public/brand/logo-lockup.png (generated by
   * `pnpm brand:assets`). Email clients don't render inline SVG, so this
   * must be a hosted raster image — callers build it from
   * `NEXT_PUBLIC_LANDING_URL` (see packages/notifications/src/channels).
   * Omit to render the wordmark alone rather than a broken image.
   */
  logoUrl?: string
}

/** Brand header dropped at the top of every transactional/alert e-mail template. */
export function EmailHeader({ logoUrl }: EmailHeaderProps) {
  return (
    <Section style={header}>
      {logoUrl && <Img src={logoUrl} width="32" height="32" alt="StockAlert" style={logo} />}
      <Text style={wordmark}>StockAlert</Text>
    </Section>
  )
}

const header = { padding: '24px 48px 0', display: 'flex', alignItems: 'center' as const }
const logo = { display: 'inline-block', verticalAlign: 'middle', marginRight: '10px' }
const wordmark = {
  display: 'inline-block',
  verticalAlign: 'middle',
  color: '#EA580C',
  fontSize: '18px',
  fontWeight: '700',
  margin: '0',
}
